tts=Kokoro("kokoro-v1.0.int8.onnx","voices-v1.0.bin")
voices=["ef_dora","em_alex","ef_dora","em_alex","ef_dora","em_alex","ef_dora","em_alex","ef_dora","em_alex","ef_dora","em_alex","ef_dora","em_alex","ef_dora","em_alex","ef_dora","em_alex","ef_dora","em_alex"]
speeds=[0.97,0.99,1.02,0.97,1.0,0.98,1.01,0.97,0.99,1.02,0.97,1.0,0.98,1.01,0.97,0.99,1.02,0.98,1.0,0.97]
manifest=[]
for i,(topic,narration) in enumerate(texts):
 samples,sr=tts.create(narration,voice=voices[i],speed=speeds[i],lang="es")
 raw=out/f"voz_{i+1:02d}_raw.wav"
 sf.write(str(raw),samples,sr,subtype="PCM_16")
 clean=out/f"VOZ_{i+1:02d}.wav"
 subprocess.run(["ffmpeg","-y","-loglevel","error","-i",str(raw),"-af","highpass=f=75,lowpass=f=11000,acompressor=threshold=-23dB:ratio=1.8:attack=10:release=110,alimiter=limit=0.95","-ar","24000",str(clean)],check=True)
 raw.unlink()
 duration=len(samples)/sr
 manifest.append(dict(index=i+1,subject=topic,voice=voices[i],duration_s=round(duration,2)))
 print(f"VOICE {i+1}/20, {duration:.2f}s",flush=True)
(out/"manifest.json").write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding="utf-8")
with zipfile.ZipFile(out/"AUDIOS_NEURALES_SYSTERAPRIME_V02.zip","w",zipfile.ZIP_DEFLATED,compresslevel=5) as z:
 for f in out.glob("VOZ_*.wav"): z.write(f,arcname=f.name)
 z.write(out/"manifest.json",arcname="manifest.json")
